    ["WorldEvents"] = "Eventos del mundo",
    ["Leveling Rank (Difficulty/Completeness)"] = "Rango Nivel (Dificultad/Exhaustividad)",
    ["Dailies Rank (Difficulty/Completeness)"] = "Rango Misiones diarias (Dificultad/Exhaustividad)",
    ["Profession Rank (Difficulty/Completeness)"] = "Rango Profesiones (Dificultad/Exhaustividad)",
    ["Achievements Rank (Difficulty/Completeness)"] = "Rango Logros (Dificultad/Exhaustividad)",
    ["WorldEvents Rank (Difficulty/Completeness)"] = "Rango Eventos del mundo (Dificultad/Exhaustividad)",
