    -- Dialog and button strings (WoWPro_Frames.lua).
    ["Resize guide window"] = "Cambiar el tamaño de la ventana de la guía",
    ["Okay"] = "Aceptar",
    ["Cancel"] = "Cancelar",
    ["Skipping the step |cFFFFFF00%s|r will also cause the following steps to skip:\n|cFFFFFF00%s|r\nIf you wanted to just complete the step, |cffff0000cancel|r this dialog and right-click instead.\n"] = "Omitir el paso |cFFFFFF00%s|r también hará que se omitan los siguientes pasos:\n|cFFFFFF00%s|r\nSi solo querías completar el paso, |cffff0000cancela|r este diálogo y haz clic derecho en su lugar.\n",
    ["Discord Server!"] = "¡Servidor de Discord!",
    ["Connect with other players, get help, and stay updated!"] = "Conecta con otros jugadores, consigue ayuda y mantente al día.",
    ["Copy"] = "Copiar",
    ["Close"] = "Cerrar",
    ["Load Next Guide"] = "Cargar la siguiente guía",
    ["Choose Guide From List"] = "Elegir guía de la lista",
    -- Configuration section headers (WoWPro_Config.lua).
    ["Behavior"] = "Comportamiento",
    ["Button Display Options"] = "Opciones de visualización de botones",
    ["Window Layout"] = "Diseño de la ventana",
    ["Position & Anchor"] = "Posición y anclaje",
    ["Window Sizing"] = "Tamaño de la ventana",
    ["Content Spacing"] = "Espaciado del contenido",
    ["Appearance"] = "Apariencia",
    ["Guide Behavior"] = "Comportamiento de la guía",
    ["About"] = "Acerca de",
    ["What WoW-Pro Does"] = "Qué hace WoW-Pro",
    ["Where To Start"] = "Por dónde empezar",
    ["Runtime Status"] = "Estado de ejecución",
    ["Stay Connected"] = "Mantente conectado",
    ["Discord Invite"] = "Invitación de Discord",
    ["Source Repository"] = "Repositorio de código",
    ["Help"] = "Ayuda",
    ["Getting Started"] = "Primeros pasos",
    ["Starting WoW-Pro"] = "Iniciar WoW-Pro",
    ["Exporting And Sharing"] = "Exportar y compartir",
    ["Default is 0.5 seconds."] = "El valor predeterminado es 0,5 segundos.",
    -- About tab, command list, and help paragraphs (WoWPro_Config.lua).
    ["WoW-Pro is a community-built addon collection that helps with questing, leveling, and guide-driven progression."] = "WoW-Pro es una colección de complementos creada por la comunidad que ayuda con las misiones, la subida de nivel y la progresión guiada.",
    ["It has grown through years of player contributions, covering content from legacy expansions through current Retail."] = "Ha crecido durante años gracias a las contribuciones de los jugadores, cubriendo contenido desde expansiones antiguas hasta el Retail actual.",
    ["New here: begin with Main and Guide Display to set automation, layout, and text style."] = "¿Nuevo por aquí? Empieza con General y Visualización de la guía para configurar la automatización, el diseño y el estilo del texto.",
    ["Troubleshooting: open Main > Tools for logging and About > Commands for command shortcuts."] = "Solución de problemas: abre General > Herramientas para los registros y Acerca de > Comandos para los atajos de comandos.",
    ["Use these links for announcements, support, and development updates."] = "Usa estos enlaces para anuncios, soporte y novedades de desarrollo.",
    ["Tip: Include your guide name or ID and a short log snippet when asking for help in Discord."] = "Consejo: incluye el nombre o ID de tu guía y un fragmento del registro cuando pidas ayuda en Discord.",
    ["Use /wp or /wow-pro with the following commands:"] = "Usa /wp o /wow-pro con los siguientes comandos:",
    ["- where: print current map position and area details"] = "- where: muestra la posición actual en el mapa y los detalles de la zona",
    ["- reset: clear WoW-Pro saved runtime state"] = "- reset: borra el estado de ejecución guardado de WoW-Pro",
    ["- clear-log / log: clear or show the debug log"] = "- clear-log / log: borra o muestra el registro de depuración",
    ["- guide-bug / trade-bug: create focused bug reports"] = "- guide-bug / trade-bug: crea informes de errores específicos",
    ["- devcoords / devzone / devmode: developer mapping helpers"] = "- devcoords / devzone / devmode: herramientas de mapas para desarrolladores",
    ["- flightids [dest]: inspect flight node IDs for your current map"] = "- flightids [dest]: inspecciona los ID de nodos de vuelo de tu mapa actual",
    -- Getting Started and Troubleshooting bullets (WoWPro_Config.lua).
    ["Start here to select a guide and set your questing preferences."] = "Empieza aquí: elige una guía y define tus preferencias de misiones.",
    ["- If steps do not advance, check Main > General automation and the Ranks page. Open Main > Tools to enable debugging and inspect the log."] = "- Si los pasos no avanzan, revisa la automatización en General > General y la página Rangos. Abre General > Herramientas para activar la depuración y revisar el registro.",
    ["- Use /wp log to inspect debug entries and /wp clear-log before reproducing issues."] = "- Usa /wp log para inspeccionar las entradas de depuración y /wp clear-log antes de reproducir el problema.",
    ["- Use /wp reset if saved state becomes inconsistent after major patches."] = "- Usa /wp reset si el estado guardado se vuelve inconsistente tras parches importantes.",
    ["- If needed, share logs and guide ID in Discord for faster support."] = "- Si es necesario, comparte los registros y el ID de la guía en Discord para obtener ayuda más rápido.",
    -- Rank, automation, and legend help text (WoWPro_Config.lua).
    ["Ranks control how many optional steps are included in guides.\n1 = shortest route (core progression only), 2 = balanced route, 3 = fullest route (most optional content).\n\nPriority for this character is: Toon Rank first, then Global Rank as fallback."] = "Los rangos controlan cuántos pasos opcionales se incluyen en las guías.\n1 = ruta más corta (solo progresión principal), 2 = ruta equilibrada, 3 = ruta más completa (la mayor cantidad de contenido opcional).\n\nPrioridad para este personaje: primero el rango del personaje y luego el rango global como respaldo.",
    ["Default rank for all characters and guides unless overridden.\n\nUse 1 for speed leveling, 2 for normal play, or 3 for completion-focused runs."] = "Rango predeterminado para todos los personajes y guías, salvo que se anule.\n\nUsa 1 para subir de nivel rápido, 2 para jugar normal o 3 para partidas centradas en completarlo todo.",
    ["Character-specific override for this toon.\n\nIf set, this value is used instead of Global Rank for this character."] = "Anulación específica para este personaje.\n\nSi se define, este valor se usa en lugar del rango global para este personaje.",
    ["Profile-level rank for this module's guide type.\n\nUse this when you want different strictness for %s than your default rank."] = "Rango a nivel de perfil para el tipo de guía de este módulo.\n\nÚsalo si quieres un rigor distinto para %s que el de tu rango predeterminado.",
    ["Adjust the delay used while waiting for WoW API state updates. Increase this if steps complete too early; decrease it if updates feel sluggish."] = "Ajusta la espera mientras se actualiza el estado de la API de WoW. Auméntala si los pasos se completan demasiado pronto; redúcela si las actualizaciones van lentas.",
    ["Action letters appear in each step and indicate what kind of step it is. Use this legend to quickly decode guide rows."] = "Las letras de acción aparecen en cada paso e indican qué tipo de paso es. Usa esta leyenda para descifrar rápidamente las filas de la guía.",
    -- Getting Started walkthrough steps (WoWPro_Config.lua).
    ["1) Click the Horn icon for the classic Guide List, or right-click the Options icon for the new Guide List. Choose a guide matching your level, campaign, or expansion."] = "1) Haz clic en el icono de cuerno para la lista de guías clásica, o haz clic derecho en el icono de opciones para la nueva lista. Elige una guía acorde a tu nivel, campaña o expansión.",
    ["2) Open Main > General for Auto Select, Auto Accept, Auto Turn-in, Quest Tracking, and Auto-Load Guide. Use Main > Guide Modifiers to choose optional content."] = "2) Abre General > General para la selección automática, aceptación automática, entrega automática, seguimiento de misiones y carga automática. Usa General > Modificadores de guía para elegir contenido opcional.",
    ["3) Open Guide Display > Window Layout to adjust Position & Anchor, Window Sizing, and Content Spacing. Use Appearance for backgrounds and Text Formatting for fonts and text size."] = "3) Abre Visualización de la guía > Diseño de la ventana para ajustar Posición y anclaje, Tamaño de la ventana y Espaciado del contenido. Usa Apariencia para los fondos y Formato de texto para las fuentes y el tamaño del texto.",
    ["4) Start playing. WoW-Pro will load the selected guide into the main frame and advance steps as quests and objectives update."] = "4) Empieza a jugar. WoW-Pro cargará la guía seleccionada en la ventana principal y avanzará los pasos a medida que se actualicen las misiones y los objetivos.",
    ["5) If a guide looks stuck or out of sync, use /wp reset to clear guide state and /wp log to inspect the debug log before reporting the issue."] = "5) Si una guía parece atascada o desincronizada, usa /wp reset para borrar el estado de la guía y /wp log para revisar el registro de depuración antes de informar del problema.",
    -- Recorder walkthrough (WoWPro_Config.lua).
    ["Starting With The Recorder"] = "Empezar con el grabador",
    ["1) Enable WoWPro_Recorder in the AddOns list, then reload the UI if needed. When it is active, a recorder toolbar appears above the main WoW-Pro frame."] = "1) Activa WoWPro_Recorder en la lista de complementos y recarga la interfaz si es necesario. Cuando esté activo, aparecerá una barra de herramientas del grabador sobre la ventana principal de WoW-Pro.",
    ["2) Click New on the recorder toolbar to create a guide. Choose the guide type first, then fill in the guide fields such as Guide ID, zone, author, faction, and level range."] = "2) Haz clic en Nuevo en la barra de herramientas del grabador para crear una guía. Elige primero el tipo de guía y luego rellena los campos como ID de la guía, zona, autor, facción y rango de niveles.",
    ["3) Finish the New Guide dialog to register the guide. WoW-Pro will load that guide immediately so you can begin editing or recording steps into it."] = "3) Termina el diálogo Nueva guía para registrar la guía. WoW-Pro cargará esa guía de inmediato para que puedas empezar a editarla o a grabar pasos en ella.",
    ["4) Click Record to capture questing progress while you play. Click Stop any time you want to pause before moving, testing, or editing steps manually."] = "4) Haz clic en Grabar para capturar el progreso de las misiones mientras juegas. Haz clic en Detener cuando quieras hacer una pausa antes de moverte, probar o editar pasos manualmente.",
    ["5) Use Open to load an existing guide for editing. Use Save to write the current recorder version to your saved guides so it can be reopened later."] = "5) Usa Abrir para cargar una guía existente y editarla. Usa Guardar para escribir la versión actual del grabador en tus guías guardadas y poder reabrirla más tarde.",
    ["6) In Advanced mode, use Add to insert a step after the selected step, or use buttons such as Run, Flight, Portal, Note, and Delete to refine the route."] = "6) En modo avanzado, usa Añadir para insertar un paso después del paso seleccionado, o botones como Correr, Vuelo, Portal, Nota y Eliminar para perfeccionar la ruta.",
    ["7) Use /wpr to toggle Basic or Advanced recorder mode. Use /wpr help to list recorder slash commands, and /wpr qdebug on or off if you need extra quest API logging while testing."] = "7) Usa /wpr para alternar entre el modo de grabador básico y avanzado. Usa /wpr help para listar los comandos de barra del grabador, y /wpr qdebug on u off si necesitas registros adicionales de la API de misiones durante las pruebas.",
    ["8) After saving, reopen the guide with Open and run through a few steps to verify quest IDs, notes, and automatic completion behave the way you expect."] = "8) Tras guardar, vuelve a abrir la guía con Abrir y recorre algunos pasos para comprobar que los IDs de misión, las notas y la finalización automática funcionan como esperas.",
    -- Export and sharing steps (WoWPro_Config.lua).
    ["1) Click Save after recording or editing. The recorder opens a large text box containing the full Lua guide definition for the currently loaded guide."] = "1) Haz clic en Guardar tras grabar o editar. El grabador abre un cuadro de texto grande con la definición Lua completa de la guía cargada actualmente.",
    ["2) Copy that text and paste it into a guide file if you want to move the guide into the addon source, share it with another author, or submit it for review."] = "2) Copia ese texto y pégalo en un archivo de guía si quieres mover la guía al código fuente del complemento, compartirla con otro autor o enviarla para revisión.",
    ["3) The recorder also keeps a saved copy in WoWPro_RecorderDB, so you can reload the guide later with Open even if you have not moved it into a permanent guide file yet."] = "3) El grabador también guarda una copia en WoWPro_RecorderDB, así que puedes volver a cargar la guía más tarde con Abrir aunque aún no la hayas movido a un archivo de guía permanente.",
    ["4) For out-of-game backup or sharing, look in your WoW SavedVariables for WoWPro_Recorder.lua under WTF/Account/<account>/SavedVariables. That file stores the recorder guides saved on this installation."] = "4) Para copias de seguridad o para compartir fuera del juego, busca WoWPro_Recorder.lua en tus SavedVariables de WoW, en WTF/Account/<account>/SavedVariables. Ese archivo guarda las guías del grabador guardadas en esta instalación.",
    -- Broker popups (WoWPro_Broker.lua).
    ["Would you like to trash %s?"] = "¿Quieres destruir %s?",
    ["Please enter the quest ID to select and then click GO!"] = "Introduce el ID de la misión y haz clic en ¡Vamos!",
    ["Go!"] = "¡Vamos!",
    ["Never Mind"] = "Cancelar",
    ["quest id #"] = "ID de misión #",
    -- First-run welcome dialogs (WoWPro_Broker.lua).
    ["Welcome to WoWPro. For this addon to function, you need to enable one of the following addons: |cffFF9900WoW-|r|cff46921APro|r Achievements, |cffFF9900WoW-|r|cff46921APro|r Dailies, |cffFF9900WoW-|r|cff46921APro|r Leveling, |cffFF9900WoW-|r|cff46921APro|r Professions, or |cffFF9900WoW-|r|cff46921APro|r WorldEvents."] = "Bienvenido a WoWPro. Para que este complemento funcione, debes activar uno de los siguientes complementos: |cffFF9900WoW-|r|cff46921APro|r Logros, |cffFF9900WoW-|r|cff46921APro|r Misiones diarias, |cffFF9900WoW-|r|cff46921APro|r Nivel, |cffFF9900WoW-|r|cff46921APro|r Profesiones o |cffFF9900WoW-|r|cff46921APro|r Eventos del mundo.",
    ["Welcome to WoWPro.\n\nFor this addon to function properly, you need to install either: |cffFF9900TomTom|r or |cffFF9900Carbonite|r to supply the arrow.\n\nWoW-Pro's guides won't have their full functionality without one of them!\n\nDownload it for free from www.wowinterface.com or www.curseforge.com."] = "Bienvenido a WoWPro.\n\nPara que este complemento funcione correctamente, debes instalar |cffFF9900TomTom|r o |cffFF9900Carbonite|r para que proporcione la flecha.\n\n¡Las guías de WoW-Pro no tendrán toda su funcionalidad sin uno de ellos!\n\nDescárgalo gratis desde www.wowinterface.com o www.curseforge.com.",
    -- Step-problem report dialog (WoWPro_CurrentGuide.lua).
    ["WoWPro - Report Step Problem"] = "WoWPro - Informar de un problema de paso",
    ["1. Copy the Discord invite below (Ctrl+C) and open it in your browser.\n2. Copy the details below and paste them into Discord, then describe what went wrong."] = "1. Copia la invitación de Discord de abajo (Ctrl+C) y ábrela en tu navegador.\n2. Copia los detalles de abajo, pégalos en Discord y describe qué salió mal.",
    ["Select details"] = "Seleccionar detalles",
    ["Select invite"] = "Seleccionar invitación",
    ["Faction: %s\nGuide: %s\nRank: %s (%s)"] = "Facción: %s\nGuía: %s\nRango: %s (%s)",
    -- Selector, nil-guide, error log, and step-action tooltips.
    ["Stop asking to switch to this guide.\nResetting the guide will re-enable asking to switch."] = "Dejar de preguntar si cambiar a esta guía.\nRestablecer la guía volverá a activar la pregunta.",
