    -- Recorder step-editor descriptions, part 1.
    ["Check if this is a chat step."] = "Marca si es un paso de chat.",
    ["Check if this is a quest completion step NOT involving combat."] = "Marca si es un paso de finalización de misión SIN combate.",
    ["Check if this is an optional step."] = "Marca si es un paso opcional.",
    ["Check if this is an sticky step."] = "Marca si es un paso fijado.",
    ["Check if this is an unsticky step."] = "Marca si es un paso no fijado.",
    ["Choose the quest you'd like to base this step on:"] = "Elige la misión en la que basar este paso:",
    ["Are you sure you want to delete this step?\n"] = "¿Seguro que quieres eliminar este paso?\n",
    ["Are you sure you want to delete this guide? This action cannot be undone.\n\n"] = "¿Seguro que quieres eliminar esta guía? Esta acción no se puede deshacer.\n\n",
    ["The step's type."] = "El tipo de paso.",
    ["The main text for this step - often the quest name."] = "El texto principal de este paso: a menudo, el nombre de la misión.",
    ["The main text for this step - often the quest title."] = "El texto principal de este paso: a menudo, el título de la misión.",
    -- Recorder step-editor descriptions, part 2.
    ["Insert your current location and zone"] = "Insertar tu ubicación y zona actuales",
    ["Jump to a step index while staying in the editor."] = "Saltar al índice de un paso sin salir del editor.",
    ["Open a numbered list of every step in the current guide."] = "Abre una lista numerada de todos los pasos de la guía actual.",
    ["Registers the guide to be used. Current guide will be lost unless saved."] = "Registra la guía para su uso. La guía actual se perderá si no se guarda.",
    ["The guide's type determines what kind of events will be listened for."] = "El tipo de guía determina qué eventos se escuchan.",
    ["The quest you choose will determine what values are loaded into the step editor."] = "La misión elegida determina qué valores se cargan en el editor de pasos.",
    ["The rank of the step. If you are unsure, leave it as 1."] = "El rango del paso. Si no estás seguro, déjalo en 1.",
    ["This step will be marked complete when you reach this level."] = "Este paso se marcará como completado cuando alcances este nivel.",
    ["The quest tied to this step. If this quest is complete, this step will be checked off."] = "La misión vinculada a este paso. Si se completa, el paso se marcará.",
    ["You need a zone tag if the coordinates lead to a point outside the guide's title zone."] = "Necesitas una etiqueta de zona si las coordenadas llevan a un punto fuera de la zona del título de la guía.",
    ["Makes a run step complete based on coordinates rather than zone name."] = "Hace que un paso de carrera se complete según las coordenadas en lugar del nombre de la zona.",
    ["Makes a run step complete based on coordinates rather than zone name. (CC)"] = "Hace que un paso de carrera se complete según las coordenadas en lugar del nombre de la zona. (CC)",
    ["Makes a run step complete based on a series of coordinates, followed in order."] = "Hace que un paso de carrera se complete según una serie de coordenadas, seguidas en orden.",
    ["Makes a run step complete based on a series of coordinates, followed in order. (CS)"] = "Hace que un paso de carrera se complete según una serie de coordenadas, seguidas en orden. (CS)",
    ["Do not complete based on coordinates. Just show the dots. (CN)"] = "No completar según las coordenadas. Solo mostrar los puntos. (CN)",
    -- Recorder step-editor descriptions, part 3.
    ["All guides are listed here, including those that come with the addon and those you have created using the recorder."] = "Todas las guías se muestran aquí, incluidas las que vienen con el complemento y las que creaste con el grabador.",
    ["Details on how to complete this step of the guide. No more than one or two sentences, please."] = "Detalles sobre cómo completar este paso de la guía. No más de una o dos frases, por favor.",
    ["Details on how to complete this step of the guide. No more than one or two sentences, please. Only leave blank for blatantly obvious steps."] = "Detalles sobre cómo completar este paso de la guía. No más de una o dos frases, por favor. Déjalo en blanco solo para pasos obvios.",
    ["Displayed if the user has the profession at the required skill level. Please enter in the form of 'Profession SkillLevel'."] = "Se muestra si el usuario tiene la profesión con el nivel requerido. Introduce en el formato 'Profesión Nivel'.",
    ["Enter coordinates for the step here, in the form '##.##,##.##'. Seperate multiple coordinates with semicolons (;)"] = "Introduce aquí las coordenadas del paso, en el formato '##.##,##.##'. Separa varias coordenadas con punto y coma (;).",
    ["Full emitted guide lines for the current guide. The selected step is prefixed with >>."] = "Líneas de guía completas del guía actual. El paso seleccionado lleva el prefijo >>.",
    ["If a particular quest must be active, list it's QID here. Seperate multiple actives with AND/OR (&^)"] = "Si una misión concreta debe estar activa, indica su QID aquí. Separa varias activas con AND/OR (&^).",
    ["If it would be helpful to provide an easy way to target a named mob, enter the mob's name here. Use only for hard to find mobs."] = "Si sería útil ofrecer una forma sencilla de seleccionar un enemigo con nombre, introduce su nombre aquí. Úsalo solo para enemigos difíciles de encontrar.",
    ["If the quest has a prerequisite, list it's QID here. Seperate multiple prerequisites with AND/OR (&^)"] = "Si la misión tiene un requisito previo, indica su QID aquí. Separa varios requisitos con AND/OR (&^).",
    ["If the step compeltes when you loot a certain number of items, put the number here."] = "Si el paso se completa al saquear cierta cantidad de objetos, pon el número aquí.",
    ["If the step completes based on a scenario stage or objective, put the stage (or stage and objective separated by a ;) here."] = "Si el paso se completa según una etapa u objetivo de escenario, pon la etapa (o etapa y objetivo separados por ;) aquí.",
    ["If the step completes based on one or two quest objectives, not the whole quest, you can enter the quest objective here. Seperate multiple objectives with semicolons (;)"] = "Si el paso se completa según uno o dos objetivos de misión y no la misión completa, puedes introducir el objetivo de misión aquí. Separa varios objetivos con punto y coma (;).",
    ["If the step completes when you loot an item, put it's ID here."] = "Si el paso se completa al saquear un objeto, pon su ID aquí.",
    ["If the step requires you to use an item, put it's ID here."] = "Si el paso requiere usar un objeto, pon su ID aquí.",
    ["If this quest is a Lead-In to another quest (meaning that other quest CAN be completed without this one, and doing so makes this quest no longer available), please list the quest it leads to's QID here."] = "Si esta misión es una introducción a otra (la otra misión PUEDE completarse sin esta, y hacerlo hace que esta misión deje de estar disponible), indica aquí el QID de la misión a la que lleva.",
    ["Would you like to automatically populate some fields of the step based on a quest from your log? You can edit it afterwards."] = "¿Quieres rellenar automáticamente algunos campos del paso a partir de una misión de tu registro? Puedes editarlos después.",
    -- Guide list column headers (WoWPro_Templates.lua).
    ["Zone"] = "Zona",
    ["Content"] = "Contenido",
    ["Author"] = "Autor",
    ["Progress"] = "Progreso",
